import requests

BASE_URL = "http://localhost:8001"
USERNAME = "admin@example.com"
PASSWORD = "password"
TIMEOUT = 30

def get_auth_token(email, password):
    url = f"{BASE_URL}/login"
    try:
        response = requests.post(url, json={"email": email, "password": password}, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Login request failed: {e}"

    assert response.status_code == 200, f"Login failed, status code {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Login response is not valid JSON"

    token = data.get('token') or data.get('access_token')
    assert token, "No auth token found in login response"

    return token

def test_get_all_doctors_endpoint():
    token = get_auth_token(USERNAME, PASSWORD)

    url = f"{BASE_URL}/hms/doctors"
    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {token}"
    }
    try:
        response = requests.get(url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to get all doctors failed: {e}"

    # Assert status code
    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    # Assert content-type
    content_type = response.headers.get("Content-Type", "")
    assert "application/json" in content_type, f"Expected JSON response, got Content-Type: {content_type}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Assert response is a list (or dict with list)
    assert isinstance(data, list), f"Expected response to be a list of doctors, got {type(data)}"

    if len(data) > 0:
        # Check doctor data format for first item
        doctor = data[0]
        expected_fields = {
            "first_name": str,
            "last_name": str,
            "email": str,
            "phone": str,
            "department_id": int,
            "specialization": str,
        }
        for field, field_type in expected_fields.items():
            assert field in doctor, f"Doctor object missing expected field: {field}"
            # None type could be possible, so check only if not None
            if doctor[field] is not None:
                if field_type == int:
                    assert isinstance(doctor[field], int), f"Field '{field}' expected type int, got {type(doctor[field])}"
                else:
                    assert isinstance(doctor[field], str), f"Field '{field}' expected type str, got {type(doctor[field])}"

test_get_all_doctors_endpoint()

import requests

BASE_URL = "http://localhost:8001"
AUTH_EMAIL = "admin@example.com"
AUTH_PASSWORD = "password"
TIMEOUT = 30

def get_auth_token():
    url = f"{BASE_URL}/login"
    headers = {"Accept": "application/json"}
    payload = {
        "email": AUTH_EMAIL,
        "password": AUTH_PASSWORD
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
        response.raise_for_status()
    except requests.RequestException as e:
        assert False, f"Authentication request failed: {e}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Authentication response is not valid JSON"

    # Expecting a token in the response to use with Bearer Auth
    # The PRD does not specify exact token format, so assume token is in 'token' key
    token = data.get('token')
    assert token is not None and isinstance(token, str), "Authentication token not found or invalid"
    return token


def test_get_all_appointments_endpoint():
    token = get_auth_token()
    url = f"{BASE_URL}/hms/appointments"
    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {token}"
    }
    try:
        response = requests.get(url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to get all appointments failed: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    appointments = None
    if isinstance(data, list):
        appointments = data
    elif isinstance(data, dict):
        if 'data' in data and isinstance(data['data'], list):
            appointments = data['data']
        else:
            assert False, "Response JSON structure unexpected: expected list or dict with 'data' list"

    for appointment in appointments:
        assert isinstance(appointment, dict), "Each appointment item should be a dict"
        assert "patient_id" in appointment and isinstance(appointment["patient_id"], int), "Appointment missing valid 'patient_id'"
        assert "doctor_id" in appointment and isinstance(appointment["doctor_id"], int), "Appointment missing valid 'doctor_id'"
        assert "appointment_date" in appointment and isinstance(appointment["appointment_date"], str), "Appointment missing valid 'appointment_date'"
        assert "appointment_time" in appointment and isinstance(appointment["appointment_time"], str), "Appointment missing valid 'appointment_time'"
        if "reason" in appointment:
            assert isinstance(appointment["reason"], str), "'reason' should be a string if present"


